  const AudioContext = window.AudioContext || window.webkitAudioContext;
  const audioCtx = new AudioContext();
  // Ensure AudioContext is resumed on first user interaction
  const resumeAudio = () => { if (audioCtx.state === 'suspended') audioCtx.resume(); };
  canvas.addEventListener('mousedown', resumeAudio, { once: true });
  canvas.addEventListener('touchstart', resumeAudio, { once: true });

  // Thrust sound (short beep)
  function playThrust() {
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.frequency.value = 300;
    gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.15);
    osc.connect(gain).connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + 0.15);
  }

  // Crash sound (low buzz)
  function playCrash() {
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.frequency.value = 80;
    gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.6);
    osc.connect(gain).connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + 0.6);
  }

  // Simple background hum
  let bgOsc = null;
  function startBackgroundHum() {
    if (bgOsc) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.frequency.value = 40;
    gain.gain.setValueAtTime(0.03, audioCtx.currentTime);
    osc.connect(gain).connect(audioCtx.destination);
    osc.start();
    bgOsc = osc;
  }
  function stopBackgroundHum() {
    if (bgOsc) { bgOsc.stop(); bgOsc = null; }
  }

